import "fmt"

type Counter struct { N int }
func (c Counter) CopyTick() { c.N++ }
func (c *Counter) Tick() { c.N++ }

func main() {
    c := Counter{}
    c.CopyTick(); c.Tick()
    fmt.Println(c.N)
}

