import ("fmt"; "sync")

func main() {
    var mu sync.Mutex; var wg sync.WaitGroup
    count := 0; wg.Add(2)
    for i := 0; i < 2; i++ { go func(){ mu.Lock(); count++; mu.Unlock(); wg.Done() }() }
    wg.Wait(); fmt.Println(count)
}

