import "fmt"

func main() {
    in := make(chan int); out := make(chan int)
    go func(){ for i:=1; i<=3; i++ { in <- i }; close(in) }()
    go func(){ for n := range in { out <- n*2 }; close(out) }()
    for n := range out { fmt.Println(n) }
}

