package main

import ("fmt"; "runtime")

func main() {
    var before, after runtime.MemStats
    runtime.ReadMemStats(&before)
    for i:=0; i<3; i++ { data:=make([]int,4); fmt.Println(len(data)) }
    runtime.ReadMemStats(&after)
    fmt.Println(after.Mallocs-before.Mallocs)
}

